    "Base price se upar jo chahe — poora extra aapka margin.": "বেস দামের উপরে যা খুশি — পুরো অতিরিক্তটাই আপনার মার্জিন।",
    "Black & White aur Colour ke liye alag printer selection": "সাদা-কালো ও রঙিনের জন্য আলাদা প্রিন্টার বাছাই",
    "Ye details abhi note kar lijiye — dobara nahi dikhengi.": "এই তথ্যগুলি এখনই লিখে রাখুন — আর দেখানো হবে না।",
