    "Do tarike hain — (1) apne Shop Dashboard ke Support tab me": "দুটি উপায় আছে — (1) নিজের দোকান ড্যাশবোর্ডের Support ট্যাবে",
    "Ghumana, kaatna, ujaala-gehra, ya aur document jodna ho to": "ঘোরাতে, কাটতে, আলো-গাঢ় ঠিক করতে, বা আরেকটি ডকুমেন্ট যোগ করতে হলে",
    "QR based smart printing — Scan → Upload → Pay → Auto Print": "QR ভিত্তিক স্মার্ট প্রিন্টিং — স্ক্যান → আপলোড → পেমেন্ট → অটো প্রিন্ট",
