    "₹%d below base ₹%d — allowed, your choice": "বেস ₹%d-এর থেকে ₹%d কম — অনুমোদিত, আপনার পছন্দ",
    "Install the software, then enter the Serial Key and Shop ID you receive.": "সফটওয়্যার ইনস্টল করুন, তারপর পাওয়া সিরিয়াল কী ও Shop ID দিন।",
