    "You sell three plans and you set your own price for each — any amount you like. The base is only our reference price: the difference is your margin per shop. Monthly and Yearly shops must renew (their renewal payment also comes to your gateway); Lifetime is paid once.": "আপনি তিনটি প্ল্যান বিক্রি করেন, প্রতিটির দাম নিজেই ঠিক করুন — যত খুশি। বেস শুধু আমাদের রেফারেন্স দাম: পার্থক্যটাই প্রতি দোকানে আপনার মার্জিন। মাসিক ও বার্ষিক দোকানগুলোকে রিনিউ করতে হয় (তাদের রিনিউয়াল পেমেন্টও আপনার gateway-তেই আসে); লাইফটাইম একবারই পেমেন্ট।"
