    "Range ka fixed price": "এই রেঞ্জের নির্ধারিত দাম",
    "Ek A4 sheet par passport photos (30×39 mm, 40 tak). Teen tareeke hain — jo chahiye ON karo, baaki OFF. Ek se zyada ON ho to pehle photo-range, phir har-photo, phir sheet ka rate lagta hai. Sab OFF = aapka Color per-page rate.": "একটি A4 শিটে পাসপোর্ট ছবি (৩০×৩৯ মিমি, সর্বোচ্চ ৪০টি)। তিনটি উপায় — যেটা দরকার ON করুন, বাকি OFF। একাধিক ON হলে: আগে ছবি-রেঞ্জ, তারপর প্রতি ছবি, তারপর শিটের রেট। সব OFF = আপনার Color প্রতি পৃষ্ঠার রেট।",
    "1. Har photo ka rate": "১. প্রতি ছবির রেট",
    "2. Poori A4 sheet ka rate": "২. পুরো A4 শিটের রেট",
    "3. Photo-range ke hisaab se": "৩. ছবির রেঞ্জ অনুযায়ী",
    "Har range ka rate (₹ per photo) bharo — calculation (range ke aakhri photo tak) turant dikhta hai. Calculation badal kar apna total bhi set kar sakte ho: us range ka bill wahi hoga. Na badlo to bill = photo × rate.": "প্রতিটি রেঞ্জের রেট (₹ প্রতি ছবি) দিন — হিসাব সঙ্গে সঙ্গে দেখা যাবে। হিসাবের মোট বদলে নিজের মোট সেট করতে পারেন: ওই রেঞ্জের বিল ঠিক তাই হবে। না বদলালে বিল = ছবি × রেট।",
    "Calculation: range ke aakhri page × rate = total. Total badal kar apna fixed bill bhi set kar sakte ho — us range me aane wale har bill me wahi total lagega. Na badlo to bill = page × rate.": "হিসাব: রেঞ্জের শেষ পৃষ্ঠা × রেট = মোট। মোট বদলে নিজের নির্দিষ্ট বিল সেট করতে পারেন — ওই রেঞ্জের প্রতিটি বিল ঠিক সেই মোট হবে। না বদলালে বিল = পৃষ্ঠা × রেট।",
    "Duplex abhi band hai — ye daam save ho jayega, Duplex chalu karne par hi customer ko lagega.": "ডুপ্লেক্স এখন বন্ধ — এই দাম সেভ হবে; ডুপ্লেক্স চালু করলে প্রযোজ্য হবে।",
